use observer::Subject;
use std::sync::{Arc, Mutex};

#[test]
fn test_single_subscriber() {
    let mut s = Subject::new();
    let received = Arc::new(Mutex::new(vec![]));
    let r = received.clone();
    s.subscribe(move |v| r.lock().unwrap().push(v));
    s.notify(42);
    assert_eq!(*received.lock().unwrap(), vec![42]);
}

#[test]
fn test_multiple_subscribers() {
    let mut s = Subject::new();
    let a = Arc::new(Mutex::new(0i32));
    let b = Arc::new(Mutex::new(0i32));
    let ac = a.clone(); s.subscribe(move |v| *ac.lock().unwrap() += v);
    let bc = b.clone(); s.subscribe(move |v| *bc.lock().unwrap() += v * 2);
    s.notify(5);
    assert_eq!(*a.lock().unwrap(), 5);
    assert_eq!(*b.lock().unwrap(), 10);
}

#[test]
fn test_notify_multiple_times() {
    let mut s = Subject::new();
    let sum = Arc::new(Mutex::new(0i32));
    let sc = sum.clone();
    s.subscribe(move |v| *sc.lock().unwrap() += v);
    s.notify(1);
    s.notify(2);
    s.notify(3);
    assert_eq!(*sum.lock().unwrap(), 6);
}

#[test]
fn test_subscriber_count() {
    let mut s = Subject::new();
    assert_eq!(s.subscriber_count(), 0);
    s.subscribe(|_| {});
    s.subscribe(|_| {});
    assert_eq!(s.subscriber_count(), 2);
}

#[test]
fn test_no_subscribers() {
    let s = Subject::new();
    s.notify(99); // should not panic
}
